import json, urllib.request, time

BASE="https://api.ivxholding.com"

def post(url, body, headers=None, timeout=15):
    data=json.dumps(body).encode("utf-8")
    h={"Content-Type":"application/json"}
    if headers: h.update(headers)
    req=urllib.request.Request(url, data=data, headers=h, method="POST")
    try:
        import urllib.error
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.status, json.loads(r.read().decode())
    except urllib.error.HTTPError as e:
        raw=e.read().decode("utf-8",errors="replace")
        try: return e.code, json.loads(raw)
        except: return e.code, {"_raw":raw[:200]}
    except Exception as e:
        return 0, {"_error":str(e)}

# Health
import urllib.error
req=urllib.request.Request(f"{BASE}/health")
with urllib.request.urlopen(req, timeout=30) as r:
    h=json.loads(r.read().decode())
print(f"SHA={h.get('commit','?')}")
print(f"BOOT={h.get('bootTime','?')}")
print(f"STATUS={h.get('status','?')}")

# Auth
code, auth = post(f"{BASE}/api/ivx/owner-passwordless-login", {"email":"iperez4242@gmail.com","emergency":"ivx_emergency_recovery"})
token = auth.get("accessToken","")
print(f"TOKEN_LEN={len(token)}")
with open("/tmp/ea_token.txt","w") as f: f.write(token)
PYEOF

